const { reservationDate, requestedTime, partySize } = args;

const isValidIsoDate = (value) => {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
};

const isValidTime = (value) => {
  const match = typeof value === "string" && value.match(/^(\d{2}):(\d{2})$/);
  return Boolean(match) && Number(match[1]) < 24 && Number(match[2]) < 60;
};

if (!isValidIsoDate(reservationDate) || !isValidTime(requestedTime) || !Number.isInteger(partySize)) {
  return {
    available: false,
    error: "missing_or_invalid_required_information",
    alternatives: [],
  };
}

if (partySize < 1 || partySize > 8) {
  return {
    available: false,
    reason: "party_size_not_supported",
    alternatives: [],
  };
}

if (requestedTime === "18:45" || requestedTime === "20:00") {
  return {
    available: true,
    requestedTime,
    alternatives: [],
  };
}

return {
  available: false,
  requestedTime,
  alternatives: ["18:45", "20:00"],
};
